* >Natural Source Code: EODPAY
* PROGRAM: EODPAY - END OF DAY PAYMENT PROCESSING
* DESCRIPTION: BATCH PAYMENT SETTLEMENT AND RECONCILIATION
*              PROCESSES PENDING SETTLEMENTS, MATCHES GATEWAY
*              REPORTS DISCREPANCIES
* LIBRARY: RETAILCORE
* ADABAS FILES: 140 (PAYMENT), 143 (SETTLEMENT)
* CREATED: 2002-06-15  A. GARCIA
* MODIFIED: 2010-03-22 - ADDED GATEWAY RECONCILIATION
* MODIFIED: 2018-09-10 - ADDED MULTI-GATEWAY SUPPORT
* -------------------------------------------------------
DEFINE DATA
LOCAL
  1 #TODAY                (D)
  1 #YESTERDAY            (D)
*
* COUNTERS
  1 #PAYMENTS-PROCESSED   (N8)
  1 #CAPTURES-SETTLED     (N8)
  1 #REFUNDS-SETTLED      (N8)
  1 #CAPTURE-AMT          (N13.2)
  1 #REFUND-AMT           (N13.2)
  1 #NET-SETTLEMENT       (N13.2)
  1 #EXPIRED-AUTHS        (N8)
  1 #DISCREPANCIES        (N8)
*
* PAYMENT METHOD BREAKDOWN
  1 #CC-COUNT             (N8)
  1 #CC-AMT               (N13.2)
  1 #DC-COUNT             (N8)
  1 #DC-AMT               (N13.2)
  1 #GC-COUNT             (N8)
  1 #GC-AMT               (N13.2)
  1 #CA-COUNT             (N8)
  1 #CA-AMT               (N13.2)
  1 #OT-COUNT             (N8)
  1 #OT-AMT               (N13.2)
*
  1 EPY-VIEW VIEW OF PAYMENT-FILE
    2 EPY-ID               (N10)
    2 EPY-ORDER-ID         (N10)
    2 EPY-METHOD           (A2)
    2 EPY-STATUS           (A2)
    2 EPY-AMOUNT           (N11.2)
    2 EPY-CAPTURED-AMT     (N11.2)
    2 EPY-REFUNDED-AMT     (N11.2)
    2 EPY-AUTH-DATE        (D)
    2 EPY-GATEWAY-ID       (A10)
*
  1 ESL-VIEW VIEW OF SETTLEMENT-FILE
    2 ESL-PAY-ID           (N10)
    2 ESL-AMOUNT           (N11.2)
    2 ESL-TYPE             (A2)
    2 ESL-STATUS           (A2)
    2 ESL-DATE             (D)
    2 ESL-BATCH-ID         (A20)
END-DEFINE
*
MOVE *DATX TO #TODAY
MOVE #TODAY TO #YESTERDAY
SUBTRACT 1 FROM #YESTERDAY (D)
*
* -------------------------------------------------------
* LOAD PAYMENT PROCESSING CONFIGURATION
* -------------------------------------------------------
1 #CFG-VALUE    (A80)
1 #CFG-NUM      (N11.2)
1 #CFG-DATE     (D)
1 #CFG-FLAG     (A1)
1 #CFG-FOUND    (A1)
1 #AUTH-EXPIRY-DAYS  (N4)  INIT <7>
1 #MAX-RETRIES  (N4)  INIT <3>
*
CALLNAT 'CONFIGN' 'PAYMENT.AUTH.EXPIRY.DAYS'
  #CFG-VALUE #CFG-NUM #CFG-DATE #CFG-FLAG #CFG-FOUND
IF #CFG-FOUND = 'Y'
  MOVE #CFG-NUM TO #AUTH-EXPIRY-DAYS
END-IF
*
CALLNAT 'CONFIGN' 'MAX.PAYMENT.RETRIES'
  #CFG-VALUE #CFG-NUM #CFG-DATE #CFG-FLAG #CFG-FOUND
IF #CFG-FOUND = 'Y'
  MOVE #CFG-NUM TO #MAX-RETRIES
END-IF
*
CALLNAT 'CONFIGN' 'PAYMENT.TIMEOUT.SEC'
  #CFG-VALUE #CFG-NUM #CFG-DATE #CFG-FLAG #CFG-FOUND
*
* VALIDATE PROCESSING DATES
1 #DT-VALID   (A1)
1 #DT-ERR     (A60)
1 #DT-RESULT  (D)
1 #DT-STR     (A10)
1 #DT-NUM     (N5)
CALLNAT 'DATEU' 'VAL' #YESTERDAY #YESTERDAY 0 #DT-RESULT
  #DT-STR #DT-NUM #DT-VALID #DT-ERR
IF #DT-VALID NE 'Y'
  CALLNAT 'LOGERR' 800 'EODPAY: INVALID PROCESSING DATE'
    'E' 'EODPAY' *USER
  ESCAPE ROUTINE
END-IF
*
* FORMAT DATES FOR REPORT HEADER
CALLNAT 'DATEU' 'FMT' #TODAY #TODAY 0 #DT-RESULT
  #DT-STR #DT-NUM #DT-VALID #DT-ERR
1 #TODAY-STR (A10)
MOVE #DT-STR TO #TODAY-STR
*
CALLNAT 'DATEU' 'FMT' #YESTERDAY #YESTERDAY 0 #DT-RESULT
  #DT-STR #DT-NUM #DT-VALID #DT-ERR
1 #YEST-STR (A10)
MOVE #DT-STR TO #YEST-STR
*
WRITE 'RETAILCORE - END OF DAY PAYMENT PROCESSING'
WRITE '============================================'
WRITE 'RUN DATE       :' #TODAY-STR
WRITE 'SETTLEMENT DATE:' #YEST-STR
WRITE ' '
*
* STEP 1: SETTLE PENDING TRANSACTIONS
WRITE 'STEP 1: SETTLING PENDING TRANSACTIONS...'
1 #BATCH-ID (A20)
COMPRESS 'BATCH-' #TODAY INTO #BATCH-ID LEAVING NO SPACE
*
FIND ESL-VIEW WITH ESL-STATUS = 'PN'
  GET ESL-VIEW *ISN (HOLD)
  MOVE 'ST' TO ESL-STATUS
  MOVE #BATCH-ID TO ESL-BATCH-ID
  MOVE #TODAY TO ESL-DATE
  UPDATE ESL-VIEW
*
  IF ESL-TYPE = 'CP'
    ADD 1 TO #CAPTURES-SETTLED
    ADD ESL-AMOUNT TO #CAPTURE-AMT
  ELSE IF ESL-TYPE = 'RF'
    ADD 1 TO #REFUNDS-SETTLED
    ADD ESL-AMOUNT TO #REFUND-AMT
  END-IF
  END-IF
*
  IF *COUNTER = 100
    END OF TRANSACTION
  END-IF
END-FIND
END OF TRANSACTION
*
* STEP 2: EXPIRE OLD AUTHORIZATIONS (>7 DAYS)
WRITE ' '
WRITE 'STEP 2: EXPIRING OLD AUTHORIZATIONS...'
1 #AUTH-CUTOFF (D)
MOVE #TODAY TO #AUTH-CUTOFF
SUBTRACT 7 FROM #AUTH-CUTOFF (D)
*
FIND EPY-VIEW WITH EPY-STATUS = 'AU'
  IF EPY-AUTH-DATE < #AUTH-CUTOFF
    GET EPY-VIEW *ISN (HOLD)
    MOVE 'EX' TO EPY-STATUS
    UPDATE EPY-VIEW
    ADD 1 TO #EXPIRED-AUTHS
    IF *COUNTER = 50
      END OF TRANSACTION
    END-IF
  END-IF
END-FIND
END OF TRANSACTION
*
* STEP 3: PAYMENT METHOD ANALYSIS
WRITE ' '
WRITE 'STEP 3: ANALYZING PAYMENTS BY METHOD...'
FIND EPY-VIEW WITH EPY-AUTH-DATE = #YESTERDAY
  ADD 1 TO #PAYMENTS-PROCESSED
  DECIDE ON FIRST VALUE OF EPY-METHOD
    VALUE 'CC'
      ADD 1 TO #CC-COUNT
      ADD EPY-AMOUNT TO #CC-AMT
    VALUE 'DC'
      ADD 1 TO #DC-COUNT
      ADD EPY-AMOUNT TO #DC-AMT
    VALUE 'GC'
      ADD 1 TO #GC-COUNT
      ADD EPY-AMOUNT TO #GC-AMT
    VALUE 'CA'
      ADD 1 TO #CA-COUNT
      ADD EPY-AMOUNT TO #CA-AMT
    NONE VALUE
      ADD 1 TO #OT-COUNT
      ADD EPY-AMOUNT TO #OT-AMT
  END-DECIDE
END-FIND
*
COMPUTE #NET-SETTLEMENT = #CAPTURE-AMT - #REFUND-AMT
*
* PRINT REPORT
WRITE ' '
WRITE 'SETTLEMENT SUMMARY'
WRITE '=================='
WRITE 'CAPTURES SETTLED   :' #CAPTURES-SETTLED
WRITE 'CAPTURE AMOUNT     :' #CAPTURE-AMT
WRITE 'REFUNDS SETTLED    :' #REFUNDS-SETTLED
WRITE 'REFUND AMOUNT      :' #REFUND-AMT
WRITE 'NET SETTLEMENT     :' #NET-SETTLEMENT
WRITE 'EXPIRED AUTHS      :' #EXPIRED-AUTHS
WRITE 'BATCH ID           :' #BATCH-ID
WRITE ' '
WRITE 'PAYMENT METHOD BREAKDOWN (YESTERDAY)'
WRITE '====================================='
WRITE 'CREDIT CARD  - COUNT:' #CC-COUNT 'AMOUNT:' #CC-AMT
WRITE 'DEBIT CARD   - COUNT:' #DC-COUNT 'AMOUNT:' #DC-AMT
WRITE 'GIFT CARD    - COUNT:' #GC-COUNT 'AMOUNT:' #GC-AMT
WRITE 'CASH         - COUNT:' #CA-COUNT 'AMOUNT:' #CA-AMT
WRITE 'OTHER        - COUNT:' #OT-COUNT 'AMOUNT:' #OT-AMT
* -------------------------------------------------------
* FORMAT SETTLEMENT AMOUNTS
* -------------------------------------------------------
1 #FMT-OUT   (A132)
1 #FMT-IN    (A80)
CALLNAT 'FMTU' 'CURR' #FMT-IN #CAPTURE-AMT ' ' 0 #FMT-OUT
WRITE 'FORMATTED CAPTURE AMT  :' #FMT-OUT
CALLNAT 'FMTU' 'CURR' #FMT-IN #REFUND-AMT ' ' 0 #FMT-OUT
WRITE 'FORMATTED REFUND AMT   :' #FMT-OUT
CALLNAT 'FMTU' 'CURR' #FMT-IN #NET-SETTLEMENT ' ' 0 #FMT-OUT
WRITE 'FORMATTED NET SETTLE   :' #FMT-OUT
*
* -------------------------------------------------------
* VALIDATE GATEWAY IDS FOR SETTLED PAYMENTS
* -------------------------------------------------------
WRITE ' '
WRITE 'STEP 4: VALIDATING GATEWAY IDS...'
1 #GW-ERRORS (N6)
1 #GW-VAL-FLAG (A1)
1 #GW-VAL-MSG  (A60)
FIND EPY-VIEW WITH EPY-AUTH-DATE = #YESTERDAY
  IF EPY-GATEWAY-ID NE ' '
    CALLNAT 'VALU' 'ALNM' EPY-GATEWAY-ID #GW-VAL-FLAG #GW-VAL-MSG
    IF #GW-VAL-FLAG NE 'Y'
      ADD 1 TO #GW-ERRORS
    END-IF
  END-IF
  IF *COUNTER > 5000
    ESCAPE BOTTOM
  END-IF
END-FIND
IF #GW-ERRORS > 0
  1 #GW-ERR-MSG (A80)
  COMPRESS 'EODPAY: ' #GW-ERRORS ' INVALID GATEWAY IDS'
    INTO #GW-ERR-MSG
  CALLNAT 'LOGERR' 801 #GW-ERR-MSG 'W' 'EODPAY' *USER
END-IF
WRITE '  GATEWAY VALIDATION ERRORS:' #GW-ERRORS
*
* -------------------------------------------------------
* LOOK UP CUSTOMER INFO FOR LARGE REFUNDS
* -------------------------------------------------------
WRITE ' '
WRITE 'STEP 5: CHECKING LARGE REFUNDS...'
1 #LARGE-REFUND-LIMIT (N11.2) INIT <500.00>
1 #CG-CUST-DATA
  2 #CG-ID       (N8)
  2 #CG-NO       (A10)
  2 #CG-TYPE     (A2)
  2 #CG-STATUS   (A1)
  2 #CG-TITLE    (A5)
  2 #CG-FNAME    (A30)
  2 #CG-LNAME    (A40)
  2 #CG-DOB      (D)
  2 #CG-GENDER   (A1)
1 #CG-CONTACT
  2 #CG-EMAIL    (A80)
  2 #CG-PH1      (A20)
  2 #CG-PH2      (A20)
  2 #CG-PH3      (A20)
1 #CG-ADDRESS
  2 #CG-ADDR1    (A40)
  2 #CG-ADDR2    (A40)
  2 #CG-CITY     (A30)
  2 #CG-STATE    (A2)
  2 #CG-ZIP      (A10)
  2 #CG-COUNTRY  (A3)
1 #CG-MEMBER
  2 #CG-MEM-FLAG (A1)
  2 #CG-MEM-ID   (A12)
  2 #CG-MEM-SINCE (D)
  2 #CG-LOY-TIER (A1)
  2 #CG-LOY-PTS  (N10)
  2 #CG-LIFE-SPEND (N11.2)
  2 #CG-YTD-SPEND  (N9.2)
1 #CG-FOUND     (A1)
1 #CG-ERR       (A60)
*
1 #REFUND-ORD-VIEW VIEW OF ORDER-FILE
  2 RFO-ID       (N10)
  2 RFO-CUST-ID  (N8)
*
FIND EPY-VIEW WITH EPY-STATUS = 'RF'
  IF EPY-REFUNDED-AMT >= #LARGE-REFUND-LIMIT
    * LOOK UP THE ORDER TO GET CUSTOMER
    FIND #REFUND-ORD-VIEW WITH RFO-ID = EPY-ORDER-ID
      IF NO RECORDS FOUND
        IGNORE
      END-NOREC
      IF RFO-CUST-ID > 0
        CALLNAT 'CUSTGET' RFO-CUST-ID #CG-CUST-DATA #CG-CONTACT
          #CG-ADDRESS #CG-MEMBER #CG-FOUND #CG-ERR
        IF #CG-FOUND = 'Y'
          WRITE '  LARGE REFUND: $' EPY-REFUNDED-AMT
            'CUSTOMER:' #CG-FNAME #CG-LNAME
        END-IF
      END-IF
      ESCAPE BOTTOM
    END-FIND
  END-IF
  IF *COUNTER > 1000
    ESCAPE BOTTOM
  END-IF
END-FIND
*
WRITE ' '
WRITE 'EOD PAYMENT PROCESSING COMPLETE'
*
* -------------------------------------------------------
* AUDIT AND LOG COMPLETION
* -------------------------------------------------------
CALLNAT 'AUDITN' 'PAY' 'EODPAY' 'U' 'BATCH'
  ' ' ' ' 'EOD PAYMENT PROCESSING COMPLETE'
*
1 #PAY-COMP-MSG (A80)
COMPRESS 'EODPAY: SETTLED=' #CAPTURES-SETTLED
  ' REFUNDS=' #REFUNDS-SETTLED ' EXPIRED=' #EXPIRED-AUTHS
  INTO #PAY-COMP-MSG
CALLNAT 'LOGERR' 0 #PAY-COMP-MSG 'I' 'EODPAY' *USER
*
END
